package com.johnny.hotel;
import com.johnny.hotel.support.WalletDevelopmentGuard;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.boot.builder.SpringApplicationBuilder;import java.sql.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="hotel.v62.fresh.smoke",matches="true")class V62FreshMigrationSmokeTest{@Test void freshV1ThroughV62AndStartup()throws Exception{var e=WalletDevelopmentGuard.settings();String db="hotel_v62_smoke_"+UUID.randomUUID().toString().replace("-","").substring(0,12),base=WalletDevelopmentGuard.url(),url=base.replace("/hotel_management?","/"+db+"?");try(var admin=DriverManager.getConnection(base,e.get("DB_USERNAME"),e.get("DB_PASSWORD"));var s=admin.createStatement()){s.execute("CREATE DATABASE `"+db+"` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");try{var f=Flyway.configure().dataSource(url,e.get("DB_USERNAME"),e.get("DB_PASSWORD")).locations("classpath:db/migration").load();assertTrue(f.migrate().migrationsExecuted>0);f.validate();try(var c=DriverManager.getConnection(url,e.get("DB_USERNAME"),e.get("DB_PASSWORD"));var q=c.createStatement();var r=q.executeQuery("SELECT (SELECT COUNT(*) FROM flyway_schema_history WHERE version='62' AND success=1),(SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('site_page','site_page_version','site_section','site_navigation','marketing_promotion','media_asset','hotel_location_content','hotel_visual_scene','scene_node_binding'))")){assertTrue(r.next());assertEquals(1,r.getInt(1));assertEquals(9,r.getInt(2));}try(var context=new SpringApplicationBuilder(HotelBackendApplication.class).run("--spring.datasource.url="+url,"--spring.datasource.username="+e.get("DB_USERNAME"),"--spring.datasource.password="+e.get("DB_PASSWORD"),"--spring.data.redis.password="+e.get("REDIS_PASSWORD"),"--server.port=0","--logging.level.org.springframework=WARN")){assertTrue(context.isActive());}}finally{s.execute("DROP DATABASE `"+db+"`");}}}}
